#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <limits>

template <typename scalar_t>
__device__ __forceinline__ float ld_as_float(const scalar_t* p) {
    return static_cast<float>(*p);
}

template <typename scalar_t>
__device__ __forceinline__ void st_from_float(scalar_t* p, float v) {
    *p = static_cast<scalar_t>(v);
}

__device__ __forceinline__ float warp_reduce_max(float v) {
    unsigned mask = 0xffffffffu;
    v = fmaxf(v, __shfl_down_sync(mask, v, 16));
    v = fmaxf(v, __shfl_down_sync(mask, v, 8));
    v = fmaxf(v, __shfl_down_sync(mask, v, 4));
    v = fmaxf(v, __shfl_down_sync(mask, v, 2));
    v = fmaxf(v, __shfl_down_sync(mask, v, 1));
    return v;
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    unsigned mask = 0xffffffffu;
    v += __shfl_down_sync(mask, v, 16);
    v += __shfl_down_sync(mask, v, 8);
    v += __shfl_down_sync(mask, v, 4);
    v += __shfl_down_sync(mask, v, 2);
    v += __shfl_down_sync(mask, v, 1);
    return v;
}

template <typename scalar_t, int WARPS_PER_BLOCK>
__global__ __launch_bounds__(WARPS_PER_BLOCK*32, 8)
void softmax_warp_kernel(scalar_t* __restrict__ y, const scalar_t* __restrict__ x,
                         int64_t N, int64_t D, int64_t xs0, int64_t ys0) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp_in_block = tid >> 5;
    int64_t global_warp = (int64_t)blockIdx.x * WARPS_PER_BLOCK + warp_in_block;
    int64_t warp_stride = (int64_t)gridDim.x * WARPS_PER_BLOCK;

    for (int64_t row = global_warp; row < N; row += warp_stride) {
        const scalar_t* row_x = x + row * xs0;
        scalar_t* row_y = y + row * ys0;
        float m = -CUDART_INF_F;
        for (int64_t col = lane; col < D; col += 32) {
            m = fmaxf(m, ld_as_float(row_x + col));
        }
        m = warp_reduce_max(m);
        m = __shfl_sync(0xffffffffu, m, 0);
        float s = 0.0f;
        for (int64_t col = lane; col < D; col += 32) {
            s += __expf(ld_as_float(row_x + col) - m);
        }
        s = warp_reduce_sum(s);
        s = __shfl_sync(0xffffffffu, s, 0);
        float inv = 1.0f / s;
        for (int64_t col = lane; col < D; col += 32) {
            float v = __expf(ld_as_float(row_x + col) - m) * inv;
            st_from_float(row_y + col, v);
        }
    }
