    for (int64_t row = global_warp; row < N; row += warp_stride) {
        const scalar_t* row_x = x + row * xs0;
        scalar_t* row_y = y + row * ys0;
        float vals[ITEMS];
        float m = -CUDART_INF_F;
#pragma unroll
        for (int i=0; i<ITEMS; ++i) {
            int64_t col = lane + i * 32;
            float a = -CUDART_INF_F;
            if (col < D) a = ld_as_float(row_x + col);
            vals[i] = a;
            m = fmaxf(m, a);
        }
        m = warp_reduce_max(m);
        m = __shfl_sync(0xffffffffu, m, 0);
        float s = 0.0f;
#pragma unroll
        for (int i=0; i<ITEMS; ++i) {
            float e = __expf(vals[i] - m);
            vals[i] = e;
            int64_t col = lane + i * 32;
            if (col < D) s += e;
        }
        s = warp_reduce_sum(s);
        s = __shfl_sync(0xffffffffu, s, 0);
        float inv = 1.0f / s;
#pragma unroll
        for (int i=0; i<ITEMS; ++i) {
            int64_t col = lane + i * 32;
            if (col < D) st_from_float(row_y + col, vals[i] * inv);
        }
    }
}

template <typename scalar_t, int BLOCK_THREADS, int ITEMS>
__global__ __launch_bounds__(BLOCK_THREADS, 2)
void softmax_block_cached_kernel(scalar_t* __restrict__ y, const scalar_t* __restrict__ x,
                          int64_t N, int64_t D, int64_t xs0, int64_t ys0) {
    __shared__ float smem[32];
    int tid = threadIdx.x, lane = tid & 31, warp = tid >> 5;
    int nwarps = BLOCK_THREADS >> 5;
    for (int64_t row = blockIdx.x; row < N; row += gridDim.x) {
        const scalar_t* row_x = x + row * xs0;
