        float vals[ITEMS];
        float m = -CUDART_INF_F;
#pragma unroll
        for (int i=0; i<ITEMS; ++i) {
            int64_t col = tid + (int64_t)i * BLOCK_THREADS;
            float a = -CUDART_INF_F;
            if (col < D) a = ld_as_float(row_x + col);
            vals[i] = a;
            m = fmaxf(m, a);
        }
        m = warp_reduce_max(m);
        if (lane == 0) smem[warp] = m;
        __syncthreads();
        float bm = (tid < nwarps) ? smem[lane] : -CUDART_INF_F;
        if (warp == 0) bm = warp_reduce_max(bm);
