        __syncthreads();
        m = smem[0];
        float s = 0.0f;
#pragma unroll
        for (int i=0; i<ITEMS; ++i) {
            int64_t col = tid + (int64_t)i * BLOCK_THREADS;
            float e = __expf(vals[i] - m);
            vals[i] = e;
            if (col < D) s += e;
        }
        s = warp_reduce_sum(s);
        if (lane == 0) smem[warp] = s;
        __syncthreads();
        float bs = (tid < nwarps) ? smem[lane] : 0.0f;
        if (warp == 0) bs = warp_reduce_sum(bs);
        if (tid == 0) smem[0] = bs;
        __syncthreads();
        float inv = 1.0f / smem[0];
#pragma unroll
        for (int i=0; i<ITEMS; ++i) {
            int64_t col = tid + (int64_t)i * BLOCK_THREADS;
            if (col < D) st_from_float(row_y + col, vals[i] * inv);
