        if (warp == 0) bm = warp_reduce_max(bm);
        if (tid == 0) smem[0] = bm;
        __syncthreads();
        m = smem[0];
        float s = 0.0f;
        for (int64_t col = tid; col < D; col += BLOCK_THREADS) s += __expf(ld_as_float(row_x + col) - m);
        s = warp_reduce_sum(s);
        if (lane == 0) smem[warp] = s;
        __syncthreads();
        float bs = (tid < nwarps) ? smem[lane] : 0.0f;
        if (warp == 0) bs = warp_reduce_sum(bs);
        if (tid == 0) smem[0] = bs;
        __syncthreads();
        float inv = 1.0f / smem[0];
        for (int64_t col = tid; col < D; col += BLOCK_THREADS) st_from_float(row_y + col, __expf(ld_as_float(row_x + col) - m) * inv);
        __syncthreads();
    }
}

template <typename scalar_t, int ITEMS>
static inline void launch_warp_cached(torch::Tensor& y, const torch::Tensor& x, int64_t N, int64_t D, int64_t xs0, int64_t ys0, int blocks, cudaStream_t stream) {
    constexpr int WPB = 8;
    softmax_warp_cached_kernel<scalar_t, WPB, ITEMS><<<blocks, WPB*32, 0, stream>>>(y.data_ptr<scalar_t>(), x.data_ptr<scalar_t>(), N, D, xs0, ys0);
}

template <typename scalar_t, int ITEMS>
static inline void launch_block_cached(torch::Tensor& y, const torch::Tensor& x, int64_t N, int64_t D, int64_t xs0, int64_t ys0, int blocks, cudaStream_t stream) {
    constexpr int BT = 256;
    softmax_block_cached_kernel<scalar_t, BT, ITEMS><<<blocks, BT, 0, stream>>>(y.data_ptr<scalar_t>(), x.data_ptr<scalar_t>(), N, D, xs0, ys0);
}

torch::Tensor softmax_forward(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "expected 2D tensor");
    TORCH_CHECK(x.is_cuda(), "expected CUDA tensor");
    auto y = torch::empty_like(x);
    int64_t N = x.size(0), D = x.size(1);
    if (N == 0 || D == 0) return y;
    int64_t xs0 = x.stride(0), ys0 = y.stride(0);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    if (D <= 16) {
        int blocks = (int)((N + 255) / 256);
        int maxb = sm_count * 16; if (blocks > maxb) blocks = maxb;
