            softmax_tiny_kernel<scalar_t><<<blocks, 256, 0, stream>>>(y.data_ptr<scalar_t>(), x.data_ptr<scalar_t>(), N, (int)D, xs0, ys0);
        });
    } else if (D <= 1024) {
        constexpr int WPB = 8;
        int64_t total_warps = N < (int64_t)sm_count * 32 ? N : (int64_t)sm_count * 32;
        int blocks = (int)((total_warps + WPB - 1) / WPB); if (blocks < 1) blocks = 1;
        AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_cached", [&] {
            if (D <= 32) launch_warp_cached<scalar_t,1>(y,x,N,D,xs0,ys0,blocks,stream);
            else if (D <= 64) launch_warp_cached<scalar_t,2>(y,x,N,D,xs0,ys0,blocks,stream);
            else if (D <= 128) launch_warp_cached<scalar_t,4>(y,x,N,D,xs0,ys0,blocks,stream);
            else if (D <= 256) launch_warp_cached<scalar_t,8>(y,x,N,D,xs0,ys0,blocks,stream);
            else if (D <= 512) launch_warp_cached<scalar_t,16>(y,x,N,D,xs0,ys0,blocks,stream);
            else launch_warp_cached<scalar_t,32>(y,x,N,D,xs0,ys0,blocks,stream);
        });
    } else if (D <= 8192) {
        int blocks = (int)((N < (int64_t)sm_count * 4) ? N : (int64_t)sm_count * 4); if (blocks < 1) blocks = 1;
        AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_block_cached", [&] {
            if (D <= 2048) launch_block_cached<scalar_t,8>(y,x,N,D,xs0,ys0,blocks,stream);
            else if (D <= 4096) launch_block_cached<scalar_t,16>(y,x,N,D,xs0,ys0,blocks,stream);
            else launch_block_cached<scalar_t,32>(y,x,N,D,xs0,ys0,blocks,stream);
        });
    } else {
        constexpr int BT = 256;
        int blocks = (int)((N < (int64_t)sm_count * 8) ? N : (int64_t)sm_count * 8); if (blocks < 1) blocks = 1;
        AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_block", [&] {
            softmax_block_kernel<scalar_t, BT><<<blocks, BT, 0, stream>>>(y.data_ptr<scalar_t>(), x.data_ptr<scalar_t>(), N, D, xs0, ys0);
        });
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
